package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ScienceLiveExamPhysicsElecBank2 {
  private const val T = "විද්‍යුතය, ගෘහස්ථ පරිපථ, චුම්භකත්වය හා ඉලෙක්ට්‍රොනික විද්‍යාව"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String = "විද්‍යුතය, චුම්භකත්වය හා ඉලෙක්ට්‍රොනික විද්‍යාව පිළිබඳ නිවැරදි කරුණකි."
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("ප්ලාස්ටික් පනාවකින් වියළි හිසකෙස් පීරූ පසු පනාව කුඩා කඩදාසි කැබලි ආකර්ෂණය කර ගන්නේ කුමන බලයක් නිසාද?", "ස්ථිති විද්‍යුත් ආකර්ෂණ බලය", "චුම්භක බලය", "ගුරුත්වාකර්ෂණය", "න්‍යෂ්ටික බලය", "ආරෝපිත පනාව උදාසීන කඩදාසිවල ප්‍රතිවිරුද්ධ ආරෝපණ ප්‍රේරණය කර ආකර්ෂණය කරයි."),
    q("නියත වෝල්ටීයතාව 6 V බැටරියකින් 2 A ධාරාවක් ගලා යන්නේ නම් පරිපථයේ ප්‍රතිරෝධය කීයද?", "3 Ω", "12 Ω", "0.33 Ω", "8 Ω", "R = V / I = 6 / 2 = 3 Ω."),
    q("සමාන 12 Ω ප්‍රතිරෝධක තුනක් සමාන්තරගතව සම්බන්ධ කළ විට ලැබෙන සමක ප්‍රතිරෝධය කීයද?", "4 Ω", "36 Ω", "12 Ω", "6 Ω", "1/R = 1/12 + 1/12 + 1/12 = 3/12 = 1/4 → R = 4 Ω."),
    q("විදුලි පරිපථයක විභව අන්තරයේ SI ඒකකය වන 'වෝල්ට් 1' (1 V) යනු කුමක්ද?", "1 C ආරෝපණයක් ගෙන යාමේදී සිදුවන කාර්යය 1 J වීම (1 J C⁻¹)", "තත්පරයට කූලොම්බ් 1", "ඇම්පියර් 1 ට ජූල් 1", "ඕම් 1 ට ජූල් 1", "V = W / Q."),
    q("වාහනයක 12 V බැටරියකින් 4 A ධාරාවක් ලබා ගන්නා ප්‍රධාන ලාම්පුවක ක්ෂමතාව කීයද?", "48 W", "3 W", "16 W", "192 W", "P = V × I = 12 × 4 = 48 W."),
    q("ලෝහ කම්බිවල උෂ්ණත්වය ඉහළ ගිය විට සාමාන්‍යයෙන් ඒවායේ විද්‍යුත් ප්‍රතිරෝධයට කුමක් සිදුවේද?", "ප්‍රතිරෝධය වැඩි වේ (ලෝහ පරමාණු වේගයෙන් කම්පනය වී ඉලෙක්ට්‍රෝන ගමනට බාධා කරයි)", "ප්‍රතිරෝධය අඩු වේ", "ප්‍රතිරෝධය ශුන්‍ය වේ", "පරිවාරක බවට පත් නොවේ", "එහෙත් සිලිකන් වැනි අර්ධ සන්නායකවල උෂ්ණත්වය වැඩි වත්ම ප්‍රතිරෝධය අඩු වේ."),
    q("විද්‍යුත් පරිපථයක භාවිත වන 'වර්ණ කේත ප්‍රතිරෝධකයක' (Colour-coded resistor) රන් පැහැති අවසන් තීරුවෙන් දක්වන්නේ කුමක්ද?", "±5% ඉවසීමේ සීමාව (Tolerance)", "ප්‍රතිරෝධය 10 Ω බව", "ප්‍රතිරෝධය මිලියනයක් බව", "ධාරා සීමාව", "රිදී තීරුව ±10% ඉවසීම දක්වයි."),
    q("විදුලි පරිපථයක 'විචල්‍ය ප්‍රතිරෝධකයක්' (Rheostat) සම්බන්ධ කිරීමේ ප්‍රධාන අරමුණ කුමක්ද?", "පරිපථයේ ගලන ධාරාව පහසුවෙන් පාලනය කිරීම", "වෝල්ටීයතාව ශුන්‍ය කිරීම", "AC ධාරාව DC කිරීම", "චුම්භකත්වය නැති කිරීම", "සර්පණ ස්පර්ශකය එහා මෙහා කර ප්‍රතිරෝධක කම්බියේ දිග වෙනස් කරයි."),
    q("ගෘහස්ථ පරිපථයක ප්‍රධාන බෙදාහැරීමේ පුවරුවේ උපකරණ නිවැරදි අනුපිළිවෙළින් සවි වන පිළිවෙළ කුමක්ද?", "විදුලි මීටරය → ප්‍රධාන විලායකය/MCB → ප්‍රධාන ස්විචය → RCCB → උප පරිපථ MCB", "RCCB → විදුලි මීටරය", "උප පරිපථ → ප්‍රධාන ස්විචය", "භූගත කම්බිය → විදුලි මීටරය", "පළමුව වැය වන ඒකක මනින මීටරය පැමිණ ඉන්පසු ආරක්ෂක ස්විච පවතී."),
    q("කිසියම් විදුලි බල්බයක් මත '60 W' හා '10 W LED' ලෙස සඳහන් බල්බ දෙකක් සමාන ආලෝකයක් ලබා දේ නම් LED බල්බය වඩා ආර්ථිකදායී වන්නේ ඇයි?", "LED බල්බය තාපය ලෙස අපතේ නොයවා ඉතා අඩු විදුලියකින් (10 W) සමාන ආලෝකයක් දෙන බැවින්", "LED බල්බය 1000 V වලින් වැඩ කිරීම", "LED තාපය නිපදවීම", "සූත්‍රිකා බල්බයේ කාර්යක්ෂමතාව 99% වීම", "සූත්‍රිකා බල්බ ශක්තියෙන් 90% ක් පමණ අනවශ්‍ය තාපය ලෙස අපතේ හරී."),
    q("විද්‍යුත් ධාරාවක තාපන ආචරණය ප්‍රයෝජනවත් නොවන (අවාසිදායක වන) අවස්ථාවක් කුමක්ද?", "විදුලි මෝටර, පරිගණක හා සම්ප්‍රේෂණ රැහැන් අධික ලෙස රත් වීම", "විදුලි ඉස්තිරික්කය", "විදුලි කේතලය", "විලායක කම්බිය", "රත් වීම නිසා පරිගණකවලට සිසිලන පංකා (Cooling fans) සවි කෙරේ."),
    q("සෘජු කම්බියක ඉහළට ධාරාවක් ගලන විට එය වටා ඇති චුම්භක බල රේඛාවල දිශාව ඉහළ සිට බලන විට කෙබඳුද?", "වාමාවර්ත (Anticlockwise) වෘත්ත", "දක්ෂිණාවර්ත වෘත්ත", "සෘජු රේඛා", "බල රේඛා නැත", "දකුණත් ග්‍රහණ නියමයෙන් මහපටැඟිල්ල ඉහළට ඇල්ලූ විට ඇඟිලි වාමාවර්තව හැරේ."),
    q("විද්‍යුත් සීනුවක (Electric bell) මිටිය සීනුවේ වදිමින් නොකඩවා නාද වන්නේ කුමක් නිසාද?", "විද්‍යුත් චුම්භකය ආමේචරය ඇද ගත් විගස ස්පර්ශක ස්ථානය විසන්ධි වී නැවත සම්බන්ධ වීම", "ස්ථිර චුම්භකය කැරකීම නිසා", "බැටරිය උණු වීම නිසා", "කම්බිය දිය වීම නිසා", "මෙම ස්වයංක්‍රීය කැඩෙන-සම්බන්ධ වන ක්‍රියාව තත්පරයට කිහිප වරක් සිදුවේ."),
    q("විදුලි දුම්රියක මෙන් චුම්භක ක්ෂේත්‍රයක තැබූ ධාරාව ගලන කම්බියක් මත ඇතිවන බලය උපරිම වන්නේ කම්බිය හා චුම්භක ක්ෂේත්‍රය අතර කෝණය කීය වූ විටද?", "90° (එකිනෙකට ලම්භක වූ විට)", "0° (සමාන්තර වූ විට)", "180°", "45°", "සන්නායකය චුම්භක ක්ෂේත්‍රයට සමාන්තර නම් බලය ශුන්‍ය වේ."),
    q("ශබ්ද විකාශන යන්ත්‍රයක (Loudspeaker) විදුලි සංඥා ශබ්ද තරංග බවට පත් වන්නේ කුමන ක්‍රියාවලිය මගින්ද?", "ස්ථිර චුම්භක ක්ෂේත්‍රය තුළ විචල්‍ය ධාරාව ගෙන යන කම්බි දඟරය කම්පනය වී කේතුව කම්පනය කිරීම", "රසායනික ප්‍රතික්‍රියාවකින්", "විද්‍යුත් විච්ඡේදනයෙන්", "ස්ථිති විද්‍යුතයෙන්", "මෙය මෝටර් මූලධර්මයේම තවත් ප්‍රායෝගික යෙදීමකි."),
    q("මයික්‍රොෆෝනයක් (Microphone) ක්‍රියා කරන ආකාරය ශබ්ද විකාශන යන්ත්‍රයට ප්‍රතිවිරුද්ධය. එහි ශක්ති පරිවර්තනය කුමක්ද?", "ධ්වනි (යාන්ත්‍රික කම්පන) ශක්තිය → විද්‍යුත් සංඥා", "විද්‍යුත් ශක්තිය → ධ්වනි", "තාප → ආලෝක", "චුම්භක → රසායනික", "කම්පන මගින් කුඩා දඟරය චුම්භක ක්ෂේත්‍රයක චලනය වී විද්‍යුත් චුම්භක ප්‍රේරණයෙන් ධාරාව උපදවයි."),
    q("සරල පරිණාමකයක ප්‍රාථමික දඟරයට වඩා ද්විතීයික දඟරයේ පොට සංඛ්‍යාව වැඩි නම් එය කුමන වර්ගයේ පරිණාමකයක්ද?", "අධිකර පරිණාමකය (Step-up transformer)", "අවකර පරිණාමකය", "සරල කෝෂය", "විලායකය", "එය අඩු AC වෝල්ටීයතාවක් වැඩි AC වෝල්ටීයතාවක් බවට නංවයි."),
    q("පරිණාමකයක හරය (Core) තනි ඝන යකඩ කුට්ටියක් ලෙස නොව 'ස්තරීකරණය කළ' (Laminated) තුනී මෘදු යකඩ තහඩු එකට අලවා සාදන්නේ ඇයි?", "සුළි ධාරා (Eddy currents) නිසා ඇති වන තාප ශක්ති හානිය අවම කිරීමට", "බර වැඩි කිරීමට", "විදුලිය නැවැත්වීමට", "චුම්භක ක්ෂේත්‍රය නැති කිරීමට", "තුනී තහඩු අතර පරිවාරක වාර්නිෂ් තට්ටු පවතී."),
    q("100% කාර්යක්ෂම පරිණාමකයක ප්‍රාථමිකය 240 V, 0.5 A සපයයි. ද්විතීයික වෝල්ටීයතාව 12 V නම් ද්විතීයිකයෙන් ලබාගත හැකි ධාරාව කීයද?", "10 A", "0.5 A", "5 A", "20 A", "VₚIₚ = VₛIₛ → 240 × 0.5 = 12 × Iₛ → 120 = 12 Iₛ → Iₛ = 10 A."),
    q("කිසියම් ඩයෝඩයක් පරිපථයේදී ධාරාව ගලා යාමට ඉඩ නොදී අවහිර කරන්නේ කුමන ආකාරයට සම්බන්ධ කළ විටද?", "පසු නැඹුරු (Reverse bias - p කොටස සෘණට හා n කොටස ධනට)", "ඉදිරි නැඹුරු (Forward bias)", "AC ලෙස පමණක්", "භූගත කළ විට", "පසු නැඹුරුවේදී සන්ධියේ හායන ස්තරය (Depletion layer) පළල් වේ."),
    q("සංඛ්‍යාංක ඉලෙක්ට්‍රොනික විද්‍යාවේ NAND ද්වාරයක් (AND + NOT) මඟින් ආදාන දෙකම '1' වූ විට ලබා දෙන ප්‍රතිදානය කුමක්ද?", "0 (LOW)", "1 (HIGH)", "2", "වෙනස් වෙමින් පවතී", "AND හි ප්‍රතිදානය 1 වන විට NOT මගින් එය 0 බවට හරවයි."),
    q("ආදාන A=0 සහ B=0 වූ විට පමණක් ප්‍රතිදානය '1' ලබා දී අනෙක් සෑම අවස්ථාවකම '0' ලබා දෙන තර්ක ද්වාරය කුමක්ද?", "NOR ද්වාරය", "OR ද්වාරය", "AND ද්වාරය", "NAND ද්වාරය", "NOR යනු OR ද්වාරයක ප්‍රතිදානය NOT කිරීමයි."),
    q("නිවසේ ආරක්ෂක අනතුරු ඇඟවීමේ පද්ධතියක, රාත්‍රිය වීම (A=1) සහ දොර විවෘත වීම (B=1) යන දෙකම එකවර සිදු වූ විට පමණක් සීනුව නාද විය යුතු නම් භාවිත කළ යුතු තර්ක ද්වාරය කුමක්ද?", "AND ද්වාරය", "OR ද්වාරය", "NOT ද්වාරය", "NOR ද්වාරය", "කොන්දේසි දෙකම සත්‍ය (1) වූ විට පමණක් ප්‍රතිදානය 1 වීමට AND ද්වාරය යොදයි."),
    q("ඉලෙක්ට්‍රොනික පරිපථයක උෂ්ණත්වය වැඩි වන විට ප්‍රතිරෝධය ශීඝ්‍රයෙන් අඩු වන සංවේදක උපාංගය (NTC) කුමක්ද?", "තර්මිස්ටරය (Thermistor)", "LDR", "විලායකය", "සූත්‍රිකා බල්බය", "ඩිජිටල් උෂ්ණත්වමාන, ගිනි අනතුරු ඇඟවීම් හා AC පාලකවල තර්මිස්ටර භාවිත කෙරේ."),
    q("සරල ධාරා (DC) සහ ප්‍රත්‍යාවර්ත ධාරා (AC) අතර මූලික වෙනස කුමක්ද?", "DC එක් දිශාවකට පමණක් ගලන අතර AC ආවර්තිතව දිශාව මාරු කරමින් ගලයි", "DC වෝල්ටීයතාව සැමවිටම 230 V වේ", "AC බැටරිවලින් ලැබේ", "DC පරිවාරක හරහා ගමන් කරයි", "බැටරි හා සූර්ය කෝෂ DC ලබා දෙන අතර ප්‍රධාන විදුලිබල පද්ධතිය AC ලබා දේ."),
    q("කිසියම් දඟරයක ප්‍රේරිත ධාරාවේ දිශාව සැමවිටම එය ඇතිවීමට හේතු වූ චුම්භක ස්‍රාව වෙනසට විරුද්ධ වන බව පවසන නියමය කුමක්ද?", "ලෙන්ස්ගේ නියමය (Lenz's law)", "ඕම් නියමය", "හුක්ගේ නියමය", "නිව්ටන්ගේ පළමු නියමය", "ලෙන්ස්ගේ නියමය ශක්ති සංස්ථිති නියමයට අනුකූල වේ."),
    q("විදුලි පරිපථයක ප්‍රතිරෝධක දෙකක් සමාන්තරගතව සම්බන්ධ කළ විට සමක ප්‍රතිරෝධය පිළිබඳ සත්‍ය වන්නේ කුමක්ද?", "සමක ප්‍රතිරෝධය කුඩාම ප්‍රතිරෝධකයේ අගයටත් වඩා අඩුය", "විශාලම ප්‍රතිරෝධකයට වඩා වැඩිය", "සරල එකතුවට සමානය", "සැමවිටම ශුන්‍ය වේ", "ධාරාවට ගමන් කිරීමට අමතර මාර්ග ලැබෙන බැවින් මුළු ප්‍රතිරෝධය අඩු වේ."),
    q("විද්‍යුත් පරිපථයක 'විද්‍යුත් ධාරාව' (Electric current) යනු කුමක්ද?", "ඒකක කාලයකදී හරස්කඩක් හරහා ගලන ආරෝපණ ප්‍රමාණය", "ඉලෙක්ට්‍රෝන ගබඩා කිරීම", "ප්‍රතිරෝධයේ විලෝමය", "වෝල්ට් ඒකකය", "I = Q / t (1 A = 1 C s⁻¹)."),
    q("සාමාන්‍යයෙන් ලෝහ කම්බියක් තුළ විද්‍යුත් ධාරාව ගලා යාමේදී සැබෑ ලෙසම චලනය වන ආරෝපණ වාහකයන් මොනවාද?", "නිදහස් ඉලෙක්ට්‍රෝන", "ධන ප්‍රෝටෝන", "නියුට්‍රෝන", "ධන ලෝහ අයන", "ලෝහ දැලිසේ ධන අයන ස්ථානගතව කම්පනය වන අතර නිදහස් ඉලෙක්ට්‍රෝන පමණක් ගමන් කරයි."),
    q("කිසියම් විදුලි මෝටරයක කාර්යක්ෂමතාව වැඩි කිරීමට හා වඩා සුමට භ්‍රමණයක් ලබා ගැනීමට කරන්නේ කුමක්ද?", "වක්‍ර චුම්භක ධ්‍රැව (Radial field) සහ දඟර කිහිපයක් භාවිත කිරීම", "දඟරයේ පොට ගණන 1 ක් කිරීම", "මෘදු යකඩ හරය ඉවත් කිරීම", "ප්ලාස්ටික් කම්බි යෙදීම", "ප්‍රබල චුම්භක හා සිහින් කම්බි පොට රාශියක් භ්‍රමණ ඝූර්ණය වැඩි කරයි."),
    q("නිවසේ ශීතකරණය හා රෙදි සෝදන යන්ත්‍රය ක්‍රියා කරන විදුලි පරිපථවල ඒවායේ විදුලි ධාරා වර්ධනය මනින කිලෝවොට් පැය මීටරය මඟින් ගණනය කරන්නේ කුමක්ද?", "නිවසේ වැය වූ මුළු විද්‍යුත් ශක්තිය (kWh වලින්)", "ක්ෂණික ධාරාව", "වෝල්ටීයතාව", "ප්‍රතිරෝධය", "E = P × t."),
    q("පරිපථයක 4 V විභව අන්තරයක් යටතේ 10 C ආරෝපණයක් ගෙන යාමේදී මුදා හැරෙන විද්‍යුත් ශක්තිය කීයද?", "40 J", "2.5 J", "0.4 J", "14 J", "W = V × Q = 4 × 10 = 40 J."),
    q("ධන ආරෝපිත ප්ලාස්ටික් බටයක් ස්පර්ශ නොකර උදාසීන පරිවාරක ලෝහ ගෝලයක් අසලට ගෙන ආ විට ලෝහ ගෝලයේ සමීප පැත්තේ ඇතිවන ආරෝපණය කුමක්ද?", "සෘණ ආරෝපණයක් (-)", "ධන ආරෝපණයක් (+)", "ආරෝපණයක් නොසෑදේ", "ගෝලය දිය වේ", "මෙය ස්ථිති විද්‍යුත් ප්‍රේරණය (Electrostatic induction) නම් වේ."),
    q("ට්‍රාන්සිස්ටරයක් ස්විචයක් ලෙස ක්‍රියා කිරීමේදී එය 'ON' (සංතෘප්ත) අවස්ථාවට පත් වන්නේ කුමන අවස්ථාවේදීද?", "පාදම-විමෝචක (Base-Emitter) සන්ධියට ප්‍රමාණවත් ඉදිරි නැඹුරු වෝල්ටීයතාවක් (~0.7 V) ලැබුණු විට", "පාදම ධාරාව ශුන්‍ය විට", "සංග්‍රාහකය ගැලවූ විට", "උෂ්ණත්වය 0 K වූ විට", "කුඩා පාදම ධාරාවක් (I_B) මගින් විශාල සංග්‍රාහක ධාරාවක් (I_C) පාලනය කළ හැක."),
    q("පරිපථ සටහනක ස්විචයක් ක්‍රියා විරහිත කර තිබුණද, ආරක්ෂිත කැතෝඩ කිරණ දෝලනේක්ෂයක (CRO) තිරය මත AC තරංගයක් සමතල හා සිරස් අක්ෂවල සෑදෙන හැඩය කුමක්ද?", "සයිනාකාර වක්‍රයක් (Sine wave)", "සෘජු තිරස් රේඛාවක්", "තනි තිතක්", "හතරැස් පෙට්ටියක්", "DC වෝල්ටීයතාවක් තිරස් සෘජු රේඛාවක් ලෙස පෙනේ."),
    q("විදුලි පරිපථයක අධි ධාරාවක් ගලා යාමෙන් ගින්නක් ඇතිවීම වැළැක්වීමට යොදන 'විලායකය' (Fuse) සෑමවිටම ක්‍රියා කරන්නේ කුමන මූලධර්මය මතද?", "ධාරාවේ තාපන ආචරණය (ධාරාව ඉක්මවූ විට රත් වී දිය වී පරිපථය බිඳීම)", "චුම්භක ප්‍රේරණය", "ආලෝක පරාවර්තනය", "ධ්වනි කම්පනය", "සිගරට් හෝ වයර් වෙනුවට නියමිත ඇම්පියර් අගයට ගැළපෙන විලායක පමණක් යෙදිය යුතුය."),
    q("නිවසක විදුලි පේනු කෙවෙනියක (Socket outlet) සිදුරු තුනෙන් ඉහළින්ම ඇති විශාලතම සිදුර සම්බන්ධ වන්නේ කුමන වයරයටද?", "භූගත (Earth) වයරයට", "සජීවී (Live) වයරයට", "උදාසීන (Neutral) වයරයට", "ඕනෑම එකකට", "ආරක්ෂාව තහවුරු කිරීමට ප්ලග් එක ගසන විට මුලින්ම Earth ඇණය ඇතුළු වී ආරක්ෂක කපාටය අරී."),
    q("ඉන්ධන ප්‍රවාහනය කරන පෙට්‍රල් බවුසරයක පිටුපසින් පොළොවේ ගෑවෙන ලෝහ දම්වැලක් එල්ලා ඇත්තේ ඇයි?", "ස්ථිති විද්‍යුත් ආරෝපණ පොළොවට බැහැර කර ගිනි ඇවිළීම වැළැක්වීමට", "රථයේ වේගය අඩු කිරීමට", "මාර්ගය මැනීමට", "අලංකාරයට", "ස්ථිති විද්‍යුත් පුළිඟුවක් පෙට්‍රල් වාෂ්පය දැල්විය හැක."),
    q("පහත සඳහන් උපාංග අතුරින් ඕම්ගේ නියමය නොපිළිපදින (Non-ohmic) උපාංගය කුමක්ද?", "සූත්‍රිකා විදුලි බුබුළ හා p-n සන්ධි ඩයෝඩය", "නියත උෂ්ණත්වයේ පවතින කොන්ස්ටන්ටන් කම්බිය", "සම්මත කාබන් ප්‍රතිරෝධකය", "නියත උෂ්ණත්වයේ නිකල් කම්බිය", "බල්බ සූත්‍රිකාවේ උෂ්ණත්වය ඉහළ යත්ම එහි ප්‍රතිරෝධය වැඩි වේ."),
    q("තඹ කම්බි දඟරයක් තුළින් චුම්භකයක් නිශ්චලව තබා ඇති විට ගැල්වනෝමීටරයේ පාඨාංකය කුමක්ද?", "ශුන්‍ය (0) වේ", "උපරිම වේ", "නොකඩවා දෙපසට වැනේ", "බැටරියක් මෙන් ස්ථිර වේ", "විද්‍යුත් ගාමක බලයක් ප්‍රේරණය වීමට නම් චුම්භකය හා දඟරය අතර සාපේක්ෂ චලිතයක් තිබිය යුතුය."),
    q("12 Ω ප්‍රතිරෝධකයක් තුළින් 0.5 A ධාරාවක් ගලන විට එහි අග්‍ර දෙක අතර විභව අන්තරය කීයද?", "6 V", "24 V", "12.5 V", "3 V", "V = IR = 0.5 × 12 = 6 V."),
    q("ශ්‍රේණිගත පරිපථයක 4 Ω සහ 8 Ω ප්‍රතිරෝධක දෙකක් 24 V සැපයුමකට සම්බන්ධ කර ඇත. පරිපථයේ ගලන ධාරාව කීයද?", "2 A", "3 A", "6 A", "1 A", "මුළු R = 4 + 8 = 12 Ω; I = 24 / 12 = 2 A."),
    q("එක සමාන සූර්ය කෝෂ දෙකක් ශ්‍රේණිගතව සම්බන්ධ කළ විට මුළු ප්‍රතිදාන වෝල්ටීයතාවයට කුමක් සිදුවේද?", "දෙගුණ වේ", "නොවෙනස්ව පවතී", "අඩකින් අඩු වේ", "ශුන්‍ය වේ", "කෝෂ ශ්‍රේණිගත කළ විට වෝල්ටීයතා එකතු වන අතර සමාන්තරගත කළ විට ධාරා ධාරිතාව වැඩි වේ."),
    q("ඉලෙක්ට්‍රොනික උපාංගවල බහුලව භාවිත වන IC (Integrated Circuit) එකක් යනු කුමක්ද?", "කුඩා සිලිකන් චිපයක් මත නිපදවා ඇති ට්‍රාන්සිස්ටර, ඩයෝඩ හා ප්‍රතිරෝධක මිලියන ගණනක පරිපථයකි", "විශාල ට්‍රාන්ස්ෆෝමරයකි", "විලායක පෙට්ටියකි", "බැටරි කෝෂයකි", "නවීන පරිගණක හා ස්මාර්ට් ජංගම දුරකථන පදනම් වන්නේ ක්ෂුද්‍ර චිප මතය."),
    q("ප්‍රතිරෝධක දෙකක් R₁ හා R₂ සමාන්තරගතව සම්බන්ධ කළ විට දෙකම තුළ සමාන වන භෞතික රාශිය කුමක්ද?", "අග්‍ර දෙක අතර විභව අන්තරය (V)", "ගලන ධාරාව (ප්‍රතිරෝධ වෙනස් නම්)", "ප්‍රතිරෝධය", "තාප උත්පාදනය", "ශ්‍රේණිගතව ඇති විට දෙකම තුළින් ගලන ධාරාව (I) සමාන වේ."),
    q("230 V විදුලි සැපයුමකින් ක්‍රියා කරන 2 kW කේතලයක් විනාඩි 15 ක් (පැය 0.25) භාවිත කළහොත් වැය වන විදුලි ඒකක ගණන කීයද?", "0.5 kWh", "2 kWh", "30 kWh", "8 kWh", "E = P × t = 2 kW × 0.25 h = 0.5 kWh."),
    q("නිවසේ එක් කාමරයක 100 W විදුලි පංකාවක් දිනකට පැය 5 බැගින් දින 30 ක් ක්‍රියාත්මක කළහොත් වැය වන මුළු ඒකක ගණන කීයද?", "15 kWh (ඒකක 15)", "150 kWh", "3 kWh", "1.5 kWh", "100 W = 0.1 kW; මුළු පැය = 5 × 30 = 150 h; E = 0.1 × 150 = 15 kWh."),
    q("විද්‍යුත් චුම්භක ප්‍රේරණය වැඩි දියුණු කර ශක්තිමත් ජනකයක් සෑදීමට යොදා ගන්නා දඟරයේ හරය සඳහා සුදුසුම ද්‍රව්‍යය කුමක්ද?", "මෘදු යකඩ (Soft iron)", "තඹ", "වීදුරු", "ලී", "මෘදු යකඩ චුම්භක ස්‍රාව රේඛා සාන්ද්‍රණය කර ක්ෂේත්‍රය ශක්තිමත් කරයි."),
    q("සජීවී පුද්ගලයෙකුට විදුලි සැර වැදුණු අවස්ථාවකදී පළමුව කළ යුතු නිවැරදිම ක්‍රියාව කුමක්ද?", "ප්‍රධාන විදුලි ස්විචය නිවා දැමීම හෝ වියළි ලී කෝටුවකින් පුද්ගලයා වයරයෙන් වෙන් කිරීම", "අතින් ඇද ඉවතට ගැනීම", "ජලය වත් කිරීම", "තෙත් රෙද්දකින් ඇල්ලීම", "පළමුව තමාගේ ආරක්ෂාව තහවුරු කර ගත යුතුය."),
    q("මෝටර් රථයක හෝ ගෘහස්ථ ආලෝක පද්ධතියක ෆ්ලුවොරසන්ට් (CFL) බල්බ හා LED බල්බ තුළ සාමාන්‍ය සූත්‍රිකා බල්බවලට වඩා ඇති පාරිසරික වාසිය කුමක්ද? (LED සඳහා)", "අඩු විදුලි පරිභෝජනය, දිගු ආයු කාලය හා රසදිය නොමැති වීම", "රසදිය බහුල වීම", "අධික තාපය පිට කිරීම", "පැය 10 කින් දැවී යාම", "CFL බල්බවල සුළු රසදිය ප්‍රමාණයක් අඩංගු බැවින් LED වඩාත් පරිසර හිතකාමී වේ."),
    q("වීදුරු දණ්ඩක හෝ ඕනෑම පරිපථයක විද්‍යුත් ධාරාව මැනීමට ඇමීටරයක් සවි කිරීමේදී එහි '+' අග්‍රය සම්බන්ධ කළ යුත්තේ කොතැනටද?", "බැටරියේ ධන (+) අග්‍රය පැත්තට", "බැටරියේ සෘණ (-) අග්‍රය පැත්තට", "ඕනෑම පැත්තකට", "භූගත කම්බියට", "DC ඇමීටර හා වෝල්ට්මීටරවල ධ්‍රැවීයතාව නිවැරදිව සවි කළ යුතුය."),
    q("සම්පූර්ණ විද්‍යුත් සන්නායක නොවන, ඒවායින් චුම්භක තැනිය නොහැකි නමුත් ස්ථිර චුම්භකයක් සෑදීමට ඉතා සුදුසු ද්‍රව්‍යය කුමක්ද?", "වානේ (Steel)", "මෘදු යකඩ", "තඹ", "ඇලුමිනියම්", "වානේ චුම්භකනය කිරීමට මඳක් අපහසු වුවද චුම්භකත්වය ස්ථිරව රඳවා ගනී."),
    q("ඩයිනමෝවක ප්‍රේරිත ධාරාවේ දිශාව හඳුනා ගැනීමට භාවිත කරන නීතිය කුමක්ද?", "ෆ්ලෙමිංගේ දකුණත් නියමය (Fleming's Right-Hand Rule)", "ෆ්ලෙමිංගේ වමත් නියමය", "බොයිල් නියමය", "හුක්ගේ නියමය", "දකුණතේ මහපටැඟිල්ල චලිත දිශාව ද දබරැඟිල්ල ක්ෂේත්‍ර දිශාව ද මැදැඟිල්ල ප්‍රේරිත ධාරා දිශාව ද පෙන්වයි."),
    q("බිත්තියට සවි කළ ප්‍රධාන ස්විචයකට (Trip switch) අමතරව අකුණු ගසන අවස්ථාවලදී පරිගණක හා රූපවාහිනී ආරක්ෂා කිරීමට කළ යුත්තේ කුමක්ද?", "පේනු කෙවෙනිවලින් ප්ලග් ගලවා ඇන්ටෙනා වයර් විසන්ධි කිරීම", "ස්විචය දමා තැබීම", "ජලය ඉසීම", "යකඩ දණ්ඩක් ඇල්ලීම", "අකුණු නිසා ඇතිවන අධි වෝල්ටීයතා ස්පන්දන (Surges) වයර් හරහා උපකරණවලට හානි කළ හැක."),
    q("නිවසේ මුළුතැන්ගෙයි තෙත් පොළොවක හෝ තෙත් අත්වලින් විදුලි ස්විච ඇල්ලීම ඉතා භයානක වන්නේ ඇයි?", "තෙත් සමේ විද්‍යුත් ප්‍රතිරෝධය ඉතා අඩු වී විශාල ධාරාවක් ගලන නිසා", "වියළි සම සන්නායකයක් වීම", "වෝල්ටීයතාව 5 V වීම", "ජලය පරිවාරකයක් වීම", "වියළි සමට ඉහළ ප්‍රතිරෝධයක් ඇති නමුත් තෙත් සමේ ප්‍රතිරෝධය ඉතා අඩුය."),
    q("ඉලෙක්ට්‍රොනික පරිපථයක 400 Ω ප්‍රතිරෝධයක් සහ 100 Ω ප්‍රතිරෝධයක් සමාන්තරගතව සම්බන්ධ කළ විට ලැබෙන සමක ප්‍රතිරෝධය කීයද?", "80 Ω", "500 Ω", "250 Ω", "125 Ω", "1/R = 1/400 + 1/100 = 5/400 → R = 400/5 = 80 Ω."),
    q("10 kΩ ප්‍රතිරෝධකයක් සහ LDR එකක් යොදා සාදන ලද විභව බෙදුම් (Potential divider) පරිපථයක LDR මත දැඩි ආලෝකය වැටුණු විට LDR හරහා විභව අන්තරයට කුමක් සිදුවේද?", "විභව අන්තරය අඩු වේ (LDR ප්‍රතිරෝධය අඩු වන බැවින්)", "විභව අන්තරය වැඩි වේ", "වෙනස් නොවේ", "100 V වේ", "V ∝ R බැවින් ප්‍රතිරෝධය අඩු වන විට ඒ හරහා වෝල්ටීයතාව ද අඩු වේ."),
    q("තනි ඩයෝඩයකින් (Half-wave) සහ ඩයෝඩ 4 ක සේතුවකින් (Full-wave) ලැබෙන ප්‍රතිදාන අතර වෙනස කුමක්ද?", "සේතුව අර්ධ චක්‍ර දෙකම ඍජුකරණය කරයි; තනි ඩයෝඩය එක් අර්ධයක් පමණි", "තනි ඩයෝඩය වඩා කාර්යක්ෂම වේ", "සේතුවෙන් AC පමණක් ලැබේ", "දෙකම සමාන වේ", "පූර්ණ තරංග ඍජුකරණයේදී ශක්ති හානිය අඩු වන අතර සුමට කිරීම පහසුය."),
    q("ද්වි-ආදාන තර්ක ද්වාර අතුරින් ආදාන දෙකම '0' වූ විට පමණක් ප්‍රතිදානය '1' ලබා දෙන මූලික නොවන ද්වාර මොනවාද?", "NAND සහ NOR ද්වාර", "AND ද්වාරය", "OR ද්වාරය", "සියලු ද්වාර", "NAND(0,0) = 1 සහ NOR(0,0) = 1."),
    q("ධන අග්‍රයට සම්බන්ධ කළ 2.5 Ω ප්‍රතිරෝධකයක් සහිත පරිපථයක අභ්‍යන්තර ප්‍රතිරෝධය 0.5 Ω ක් හා විද්‍යුත් ගාමක බලය 6 V වූ බැටරියක් ඇත. ගලන ධාරාව කීයද?", "2 A", "2.4 A", "12 A", "3 A", "මුළු R = 2.5 + 0.5 = 3.0 Ω; I = E / (R + r) = 6 / 3 = 2 A."),
    q("ස්වර්ණ පත්‍ර විද්‍යුත් දර්ශකයක (Gold-leaf electroscope) ලෝහ තැටියට ධන ආරෝපිත දණ්ඩක් ළං කළ විට පත්‍ර දෙක ඈත් වන්නේ ඇයි?", "පත්‍ර දෙකටම සජාතීය (ධන) ආරෝපණ ප්‍රේරණය වී විකර්ෂණය වීම", "විකර්ෂණය නැති වී ආකර්ෂණය වීම", "වාතය රත් වීම", "පත්‍ර දිය වීම", "පහළ කෙළවරේ පත්‍ර දෙකම ධන ආරෝපිත වූ විට එකිනෙක තල්ලු කර ඈත් වේ."),
    q("වියළි දිනකදී කාර් රථයකින් බැස ලෝහ දොර ඇල්ලූ සැණින් කුඩා විදුලි පුළිඟුවක් දැනෙන්නේ ඇයි?", "සිරුරේ රැස් වූ ස්ථිති විද්‍යුත් ආරෝපණ ලෝහ දොර හරහා විසර්ජනය වීම", "කාර් බැටරිය කාන්දු වීම", "දොර රත් වී තිබීම", "චුම්භක ක්ෂේත්‍රය නිසා", "ඇඳුම් හා ආසන අතර ඝර්ෂණයෙන් ස්ථිති විද්‍යුත් ආරෝපණ ගොඩනැගේ."),
    q("ධාරාව 4 A වන අතර ප්‍රතිරෝධය 5 Ω වූ සන්නායකයක අග්‍ර දෙක අතර විභව අන්තරය කීයද?", "20 V", "1.25 V", "0.8 V", "9 V", "V = I × R = 4 × 5 = 20 V."),
    q("1.5 V වියළි කෝෂ තුනක් ශ්‍රේණිගතව සම්බන්ධ කර සාදාගත් ටෝච් බැටරියක මුළු විද්‍යුත් ගාමක බලය කීයද?", "4.5 V", "1.5 V", "3.0 V", "0.5 V", "ශ්‍රේණිගත කෝෂවල EMF එකතු වේ: 1.5 + 1.5 + 1.5 = 4.5 V."),
    q("8 Ω සහ 8 Ω ප්‍රතිරෝධක දෙකක් සමාන්තරගතව සම්බන්ධ කළ විට සමක ප්‍රතිරෝධය කීයද?", "4 Ω", "16 Ω", "8 Ω", "2 Ω", "1/R = 1/8 + 1/8 = 2/8 = 1/4 → R = 4 Ω."),
    q("5 Ω, 10 Ω සහ 15 Ω ප්‍රතිරෝධක තුනක් ශ්‍රේණිගතව සම්බන්ධ කළ විට මුළු ප්‍රතිරෝධය කීයද?", "30 Ω", "2.73 Ω", "15 Ω", "10 Ω", "ශ්‍රේණිගත පරිපථයේදී R = 5 + 10 + 15 = 30 Ω."),
    q("20 V විභව අන්තරයක් යටතේ 4 A ධාරාවක් ගලන පරිපථයක විද්‍යුත් ක්ෂමතාව කීයද?", "80 W", "5 W", "0.2 W", "24 W", "P = V × I = 20 × 4 = 80 W."),
    q("500 W විදුලි ඉස්තිරික්කයක් පැය 4 ක් භාවිත කළ විට වැය වන විද්‍යුත් ශක්තිය කිලෝවොට් පැය (kWh) වලින් කීයද?", "2 kWh", "2000 kWh", "0.5 kWh", "125 kWh", "500 W = 0.5 kW; E = 0.5 kW × 4 h = 2 kWh."),
    q("සූත්‍රිකා විදුලි බල්බයකට ලබා දෙන 100 J විද්‍යුත් ශක්තියෙන් ආලෝක ශක්තිය බවට පත් වන්නේ 5 J පමණක් නම් එහි කාර්යක්ෂමතාව කීයද?", "5%", "95%", "20%", "50%", "කාර්යක්ෂමතාව = (ප්‍රයෝජනවත් ආලෝක ප්‍රතිදානය / මුළු ආදානය) × 100% = (5/100)×100% = 5%."),
    q("ලෝහමය බඳක් ඇති විදුලි කේතල හා රෙදි සෝදන යන්ත්‍ර සඳහා ඇණ 3 ප්ලග් එකක් (Three-pin plug) භාවිත කිරීම අනිවාර්ය වන්නේ ඇයි?", "භූගත සම්බන්ධතාව මගින් විදුලි සැර වැදීම වැළැක්වීමට", "විදුලිය ඉතිරි කිරීමට", "ජලය උණු කිරීමට", "වෝල්ටීයතාව 500 V කිරීමට", "දෝෂයකදී කාන්දු ධාරාව පොළොවට ගොස් විලායකය හෝ RCCB ක්‍රියාත්මක වේ."),
    q("සූත්‍රිකා විදුලි බල්බයක් දැල්වෙන විට එහි සූත්‍රිකාව සුදු පැහැයට රත් වී දිලිසුණද සම්බන්ධක තඹ කම්බි රත් නොවන්නේ ඇයි?", "තඹ කම්බිවල ප්‍රතිරෝධය ටංස්ටන් සූත්‍රිකාවට වඩා බෙහෙවින් අඩු නිසා", "තඹ කම්බිවල ධාරාව නොගලන නිසා", "සූත්‍රිකාවේ ධාරාව 10 ගුණයක් නිසා", "තඹ පරිවාරකයක් නිසා", "සමාන I ධාරාවක් ගැලුවද H = I²Rt අනුව වැඩි තාපයක් උපදින්නේ ඉහළ R ඇති සූත්‍රිකාවෙහිය."),
    q("සූත්‍රිකා විදුලි බල්බයක් ඇතුළත වාතය ඉවත් කර ආගන් හෝ නයිට්‍රජන් වැනි නිෂ්ක්‍රිය වායුවක් පුරවා ඇත්තේ ඇයි?", "ඉහළ උෂ්ණත්වයේදී ටංස්ටන් සූත්‍රිකාව ඔක්සිකරණය වී දැවී යාම වැළැක්වීමට", "බල්බය සිසිල් කිරීමට", "වර්ණය නිල් කිරීමට", "බර අඩු කිරීමට", "ආගන් වායුව සූත්‍රිකාව වාෂ්පීභවනය වීම ද මන්දගාමී කරයි."),
    q("විද්‍යුත් චුම්භකයක් ආධාරයෙන් පරණ ලෝහ කසළ ගොඩකින් ආකර්ෂණය කර වෙන් කර ගත නොහැකි ලෝහය කුමක්ද?", "ඇලුමිනියම් හා තඹ", "යකඩ", "වානේ", "නිකල්", "ඇලුමිනියම්, තඹ, පිත්තල හා සින්ක් අචුම්භක ද්‍රව්‍ය වේ."),
    q("දණ්ඩ චුම්භකයක් වටා ඇති චුම්භක බල රේඛා රටාව කඩදාසියක් මත පැහැදිලිව නිරීක්ෂණය කිරීමට ඉසිය යුතු ද්‍රව්‍යය කුමක්ද?", "සිහින් යකඩ කුඩු (Iron filings)", "සල්ෆර් කුඩු", "ලුණු කුඩු", "වැලි", "තට්ටු කළ විට යකඩ කුඩු චුම්භක බල රේඛා දිගේ පෙළගැසේ."),
    q("එකම දිශාවට විද්‍යුත් ධාරාව ගලා යන සමාන්තර තඹ කම්බි දෙකක් එකිනෙකට ළංව තැබූ විට ඒවා අතර ඇතිවන චුම්භක අන්තර්ක්‍රියාව කුමක්ද?", "එකිනෙක ආකර්ෂණය වේ", "එකිනෙක විකර්ෂණය වේ", "කිසිදු බලයක් නැත", "චුම්භකත්වය ශුන්‍ය වේ", "ප්‍රතිවිරුද්ධ දිශාවලට ධාරා ගලන විට කම්බි දෙක එකිනෙක විකර්ෂණය වේ."),
    q("DC මෝටරයක භ්‍රමණ වේගය වැඩි කිරීමට කළ නොහැකි ක්‍රියාව කුමක්ද?", "සැපයුම් බැටරි වෝල්ටීයතාව අඩු කිරීම", "වඩා ප්‍රබල චුම්භක යෙදීම", "දඟරයේ පොට ගණන වැඩි කිරීම", "මෘදු යකඩ හරය මත දඟරය එතීම", "වෝල්ටීයතාව අඩු කළ විට ධාරාව අඩු වී බලය හා වේගය අඩු වේ."),
    q("සරල DC මෝටරයක දඟරය පූර්ණ එක් වටයක් (360°) කැරකෙන අතරතුර කොමියුටේටරය මගින් දඟරයේ ධාරාවේ දිශාව කී වතාවක් ආපසු හරවයිද?", "දෙවරක් (සෑම 180° කට වරක්)", "එක් වරක්", "හතර වතාවක්", "මාරු නොකරයි", "මේ නිසා ව්‍යාවර්තයේ දිශාව නොවෙනස්ව පවතී."),
    q("AC ඩයිනමෝවකින් ප්‍රේරිත වෝල්ටීයතාව උපරිම ශිඛර අගයකට පැමිණෙන්නේ කම්බි දඟරය චුම්භක බල රේඛාවලට කුමන පිහිටීමේදීද?", "චුම්භක බල රේඛාවලට සමාන්තරව පිහිටන මොහොතේදී", "ලම්භකව පිහිටන විට", "45° ඇලවූ විට", "නිශ්චල විට", "සමාන්තර පිහිටීමේදී දඟරයේ පැති චුම්භක රේඛා කපන සීඝ්‍රතාව උපරිම වේ."),
    q("දඟරය හරහා චුම්භක ස්‍රාවය වෙනස් වීමේ සීඝ්‍රතාව වැඩි කළ විට ප්‍රේරිත විද්‍යුත් ගාමක බලයට කුමක් සිදුවේද? (ෆැරඩේ නියමය)", "අනුලෝමව වැඩි වේ", "අඩු වේ", "ශුන්‍ය වේ", "වෙනස් නොවේ", "චුම්භකය වේගයෙන් චලනය කිරීමෙන් වැඩි විභව අන්තරයක් ජනනය කළ හැක."),
    q("ප්‍රාථමිකයේ 24 V සහ පොට 200 ක් ඇති පරිණාමකයක ද්විතීයිකයෙන් 240 V ලබා ගැනීමට ද්විතීයිකයේ පොට කීයක් තිබිය යුතුද?", "2,000", "20", "400", "240", "Nₛ = Nₚ × (Vₛ / Vₚ) = 200 × (240 / 24) = 200 × 10 = 2,000."),
    q("100% කාර්යක්ෂම පරිණාමකයක ප්‍රාථමික දඟරයට 50 W ක විද්‍යුත් ක්ෂමතාවක් සැපයූ විට ද්විතීයිකයෙන් ලබාගත හැකි උපරිම ක්ෂමතාව කීයද?", "50 W", "500 W", "5 W", "100 W", "පරිණාමකයක් වෝල්ටීයතාව වෙනස් කළද මුළු ශක්තිය හෝ ක්ෂමතාව නිර්මාණය නොකරයි."),
    q("පරිණාමක හරය තැනීමට වානේ වෙනුවට මෘදු යකඩ තෝරා ගන්නේ ඇයි?", "පහසුවෙන් චුම්භකනය හා විචුම්භකරණය වී ශක්ති හානි (හිස්ටෙරසිස්) අවම කරන බැවින්", "වානේ විදුලිය සන්නයනය නොකරන නිසා", "මෘදු යකඩ ලී වලට වඩා සැහැල්ලු නිසා", "මෘදු යකඩ ස්ථිර චුම්භකයක් වන නිසා", "AC ධාරාව සමඟ තත්පරයට 50 වතාවක් චුම්භක ක්ෂේත්‍රය මාරු වීමට මෘදු යකඩ සුදුසුය."),
    q("නිවසේ ඉදිරිපිට සවි කර ඇති කිලෝවොට් පැය මීටරය (kWh meter) මගින් මනිනු ලබන මූලික භෞතික රාශිය කුමක්ද?", "විද්‍යුත් ශක්තිය", "විද්‍යුත් ධාරාව", "විභව අන්තරය", "විද්‍යුත් ක්ෂමතාව", "විදුලි බිල්පත ගණනය කෙරෙන්නේ වැය කළ විද්‍යුත් ශක්ති ඒකක ගණන මතය."),
    q("ගෘහස්ථ විදුලි පරිපථයක නිවැරදිව භූගත කළ පෘථිවි පොළොවේ විභවය කොපමණ ලෙස සලකයිද?", "0 V", "230 V", "12 V", "110 V", "උදාසීන කම්බිය ද බලාගාරයේ හෝ ට්‍රාන්ස්ෆෝමරයේදී භූගත කර 0 V පමණ විභවයක තබා ගනී."),
    q("ගෘහස්ථ පරිපථයේ 230 V, 50 Hz AC සැපයුමේ ධාරාවේ දිශාව තත්පර 1 ක් තුළදී කී වතාවක් සම්පූර්ණ චක්‍ර සිදු කරයිද?", "50 වතාවක්", "100 වතාවක්", "230 වතාවක්", "25 වතාවක්", "සංඛ්‍යාතය 50 Hz යනු තත්පරයට සම්පූර්ණ චක්‍ර 50 කි (දිශා මාරු 100 කි)."),
    q("නිසඟ අර්ධ සන්නායකයක විද්‍යුත් සන්නායකතාව ඉහළ නැංවීම සඳහා III හෝ V කාණ්ඩයේ අපද්‍රව්‍ය පරමාණු සුළු ප්‍රමාණයක් එකතු කිරීම හඳුන්වන්නේ කෙසේද?", "මාත්‍රණය (Doping)", "ඍජුකරණය", "සම්මිශ්‍රණය", "විද්‍යුත් ලෝහාලේපනය", "ඉතා සුළු පරමාණු අනුපාතයකින් පවා සන්නායකතාව දහස් ගුණයකින් ඉහළ නැංවිය හැක."),
    q("සිලිකන් ස්ඵටිකයකට පංචසංයුජ (Valency 5) පොස්පරස් පරමාණුවක් මාත්‍රණය කළ විට අමතරව නිදහස් වන්නේ කුමක්ද?", "නිදහස් ඉලෙක්ට්‍රෝනයක්", "ධන කුහරයක්", "ප්‍රෝටෝනයක්", "ඇල්ෆා අංශුවක්", "ඉලෙක්ට්‍රෝන 4 ක් සහසංයුජ බන්ධන සාදන අතර 5 වැන්න සන්නයනයට නිදහස් වේ."),
    q("p-n සන්ධි ඩයෝඩයක p කොටස බැටරියේ ධන (+) අග්‍රයට හා n කොටස සෘණ (-) අග්‍රයට සම්බන්ධ කළ සැකැස්ම කුමක්ද?", "ඉදිරි නැඹුරුව (Forward bias)", "පසු නැඹුරුව (Reverse bias)", "ලුහුවත් වීම", "ධ්‍රැවීකරණය", "ඉදිරි නැඹුරුවේදී ඩයෝඩය හරහා පහසුවෙන් ධාරාව ගලා යයි."),
    q("AC සිට DC බවට පරිවර්තනය කරන පූර්ණ තරංග සේතු ඍජුකාරකයක් (Bridge rectifier) තැනීමට අවශ්‍ය ඩයෝඩ ගණන කීයද?", "4", "1", "2", "6", "මධ්‍ය ටැප් කළ පරිණාමකයකදී නම් ඩයෝඩ 2 ක් පමණක් ප්‍රමාණවත් වේ."),
    q("ඩයෝඩ සේතුවකින් පසු සමාන්තරගතව යෙදූ විශාල ධාරිත්‍රකයක් (Capacitor) සහිත බල සැපයුමක් නිවා දැමූ විගස පරිපථයේ LED බුබුළ තත්පර කිහිපයක් තුළ ක්‍රමයෙන් නිවී යන්නේ ඇයි?", "ධාරිත්‍රකයේ ගබඩා වූ විද්‍යුත් ආරෝපණ LED හරහා විසර්ජනය වීම", "LED තුළ බැටරියක් ඇති නිසා", "ඩයෝඩ ආලෝකය ගබඩා කරන නිසා", "වයර් රත් වී ඇති නිසා", "විදුලිය සපයන විට ධාරිත්‍රකය ආරෝපණය වී තිබීම මීට හේතුවයි."),
    q("පරිපථයක LDR (ආලෝක සංවේදී ප්‍රතිරෝධකය) මතට වැටෙන ආලෝක තීව්‍රතාව වැඩි වූ විට LDR හි ප්‍රතිරෝධයට කුමක් සිදුවේද?", "ප්‍රතිරෝධය ශීඝ්‍රයෙන් අඩු වේ", "ප්‍රතිරෝධය වැඩි වේ", "වෙනස් නොවේ", "අනන්ත වේ", "ආලෝක ශක්තිය නිසා වැඩි ආරෝපණ වාහකයන් නිදහස් වී සන්නායකතාව වැඩි වේ."),
    q("NPN ට්‍රාන්සිස්ටරයක පරිපථ සංකේතයේදී විමෝචක (Emitter) අග්‍රයේ ඇති ඊතලය යොමු කර ඇත්තේ කුමන දිශාවටද?", "පාදමෙන් (Base) පිටතට", "පාදම ඇතුළට", "සංග්‍රාහකය ඇතුළට", "ඊතලයක් නැත", "PNP ට්‍රාන්සිස්ටරයේදී විමෝචක ඊතලය පාදම දෙසට (ඇතුළට) යොමු කර ඇත."),
    q("AND තර්ක ද්වාරයකට ආදාන A=0 සහ B=1 ලබා දුන් විට ලැබෙන ප්‍රතිදානය කීයද?", "0", "1", "2", "වෙනස් වේ", "AND ද්වාරයක ප්‍රතිදානය 1 වන්නේ A=1 සහ B=1 වූ විට පමණි."),
    q("AND ද්වාරයක ප්‍රතිදානය NOT ද්වාරයක ආදානයට සම්බන්ධ කිරීමෙන් සෑදෙන තර්ක ද්වාරය කුමක්ද?", "NAND ද්වාරය", "NOR ද්වාරය", "OR ද්වාරය", "XOR ද්වාරය", "NAND යනු සංඛ්‍යාංක ඉලෙක්ට්‍රොනික විද්‍යාවේ විශ්ව ද්වාරයකි (Universal gate).")
  )
}


